questions.solution:
const express = require('express');
const app = express();
app.use(express.json());

const todos = [];

app.post('/todos', (req, res) => {
  const todo = { title: req.body.title };
  todos.push(todo);
  res.status(201).json(todo);
});

app.get('/todos', (req, res) => {
  res.json(todos);
});

app.listen(3000);
